function readName(text) {
  let body;
  try {
    body = JSON.parse(text);
  } catch {
    return "Unknown";            // not JSON at all
  }
  return body?.data?.users?.[0]?.profile?.name ?? "Unknown";
}

readName('{"data":{}}');   // "Unknown" instead of a crash
